// Approved prototype cues, now routed through the official effects bus.
export function createMatriarchSfx(music){const seen=new Set(),simple={sapPulse:[e=>100+e.charge*9,.1,'triangle',.065],sapCut:[()=>180,.09,'triangle',.12],sapSevered:[()=>120,.16,'sawtooth',.08],vineWarning:[()=>220,.14,'sine',.08],vineCaught:[()=>110,.15,'triangle',.12],vineCrush:[()=>75,.13,'triangle',.15],batsEmerged:[()=>560,.1,'triangle',.07]};return{reset(){seen.clear();},accept(events){for(const e of events){if(!['vineBreak','eggHatch',...Object.keys(simple)].includes(e.type))continue;const id=e.id||e.type+':'+e.beat;if(seen.has(id))continue;if(seen.size>=64)seen.delete(seen.values().next().value);seen.add(id);const t=music.ctx?.currentTime||0;if(e.type==='vineBreak'){music.tone(780,.075,'triangle',.14,t,170,.002,true);music.tone(180,.24,'sine',.12,t+.025,55,.003,true);music.tone(430,.11,'sawtooth',.045,t+.005,90,.002,true);}else if(e.type==='eggHatch'){music.tone(470,.055,'triangle',.1,t,170,.003,true);for(let i=0;i<3;i++)music.tone(620+i*170,.09,'triangle',.05,t+.05+i*.04,350,.003,true);}else{const[f,d,w,v]=simple[e.type];music.tone(f(e),d,w,v,t,undefined,.005,true);}}}};}
